/**
 * Yayindaki kayit ekraninda erken kontrolu GERCEKTEN dener:
 * kayitli bir numara yazip "Kodu gonder"e basiyor ve hatanin bu
 * ekranda cikip cikmadigina, dogrulama ekranina GECILMEDIGINE bakiyor.
 */
import puppeteer from 'puppeteer-core'
import fs from 'node:fs'

const KROM = [
  'C:/Program Files/Google/Chrome/Application/chrome.exe',
  'C:/Program Files (x86)/Google/Chrome/Application/chrome.exe',
].find((y) => fs.existsSync(y))

const TABAN = 'https://slooin.expo.app'
const CIKTI = process.argv[2]
const NUMARA = process.argv[3] ?? '05550000000'

const tarayici = await puppeteer.launch({ executablePath: KROM, headless: 'new' })
try {
  const sayfa = await tarayici.newPage()
  await sayfa.setViewport({ width: 390, height: 844, deviceScaleFactor: 2 })

  const otpCagrilari = []
  sayfa.on('request', (r) => {
    const u = r.url()
    if (u.includes('/auth/v1/otp')) otpCagrilari.push(u)
  })

  await sayfa.goto(`${TABAN}/kayit`, { waitUntil: 'networkidle0', timeout: 60000 })
  await new Promise((c) => setTimeout(c, 1200))

  const girdi = await sayfa.$('input')
  if (!girdi) throw new Error('telefon alani bulunamadi')
  await girdi.click()
  await girdi.type(NUMARA, { delay: 25 })

  const basildi = await sayfa.evaluate(() => {
    const hepsi = [...document.querySelectorAll('div,button')]
    const dugme = hepsi.find((o) => o.textContent?.trim() === 'Kodu gönder')
    if (!dugme) return false
    dugme.dispatchEvent(new MouseEvent('click', { bubbles: true }))
    return true
  })
  if (!basildi) throw new Error('"Kodu gonder" dugmesi bulunamadi')

  await new Promise((c) => setTimeout(c, 3500))

  const durum = await sayfa.evaluate(() => ({
    yol: location.pathname,
    metin: document.body.innerText,
  }))

  if (CIKTI) await sayfa.screenshot({ path: CIKTI })

  console.log('yol            :', durum.yol)
  console.log('otp cagrisi    :', otpCagrilari.length)
  console.log('hata gorunuyor :', durum.metin.includes('zaten bir hesap var'))
} finally {
  await tarayici.close()
}

