/**
 * Hiz sinirinin dayandigi IP basligini olcer: once normal cagri,
 * sonra ISTEMCININ KENDI X-Forwarded-For basligini yolladigi cagri.
 * Ikisi ayni cikarsa sinir taklit edilebiliyor demektir.
 */
import puppeteer from 'puppeteer-core'
import fs from 'node:fs'

const KROM = [
  'C:/Program Files/Google/Chrome/Application/chrome.exe',
  'C:/Program Files (x86)/Google/Chrome/Application/chrome.exe',
].find((y) => fs.existsSync(y))

const URL = process.argv[2]
const ANAHTAR = process.argv[3]

const tarayici = await puppeteer.launch({ executablePath: KROM, headless: 'new' })
try {
  const sayfa = await tarayici.newPage()
  await sayfa.goto('https://slooin.expo.app/', { waitUntil: 'domcontentloaded' })

  const sonuc = await sayfa.evaluate(
    async (url, anahtar) => {
      async function cagir(ekBaslik) {
        const r = await fetch(`${url}/rest/v1/rpc/_gecici_basliklar`, {
          method: 'POST',
          headers: {
            apikey: anahtar,
            Authorization: `Bearer ${anahtar}`,
            'Content-Type': 'application/json',
            ...ekBaslik,
          },
          body: '{}',
        })
        return r.json()
      }
      const normal = await cagir({})
      const taklit = await cagir({ 'X-Forwarded-For': '203.0.113.99' })
      return { normal, taklit }
    },
    URL,
    ANAHTAR
  )

  const ilgi = (h) =>
    Object.fromEntries(
      Object.entries(h ?? {}).filter(([k]) =>
        /forwarded|real-ip|connecting-ip|client-ip|true-client/i.test(k)
      )
    )

  console.log('NORMAL :', JSON.stringify(ilgi(sonuc.normal)))
  console.log('TAKLIT :', JSON.stringify(ilgi(sonuc.taklit)))
} finally {
  await tarayici.close()
}

