          method: 'POST',
          headers: {
            apikey: anahtar,
            Authorization: `Bearer ${anahtar}`,
            'Content-Type': 'application/json',
            // Her cagride BASKA bir uydurma kaynak adresi
            'X-Forwarded-For': `203.0.113.${i + 1}`,
