"""Test hesaplarina ORNEK profil fotografi yukler.

Amac: akistaki avatar yolunu gercekten dogrulamak. Uretilen gorseller
duz renk kareler - gercek yuz DEGIL.
"""
import struct
import zlib
import urllib.request

KOK = "C:/Users/orcns/projects/cloud/mobil/"


def env(anahtar):
    with open(KOK + ".env", encoding="utf-8") as f:
        for satir in f:
            if satir.startswith(anahtar + "="):
                return satir.split("=", 1)[1].strip()
    raise SystemExit("bulunamadi: " + anahtar)


URL = env("EXPO_PUBLIC_SUPABASE_URL")
ANAHTAR = env("SUPABASE_SERVICE_ROLE_KEY")


def png(renk, boyut=240):
    """Duz renk PNG - harici kutuphane yok."""
    r, g, b = renk
    ham = b""
    for _ in range(boyut):
        ham += b"\x00" + bytes([r, g, b]) * boyut

    def parca(tur, veri):
        return (
            struct.pack(">I", len(veri))
            + tur
            + veri
            + struct.pack(">I", zlib.crc32(tur + veri) & 0xFFFFFFFF)
        )

    return (
        b"\x89PNG\r\n\x1a\n"
        + parca(b"IHDR", struct.pack(">IIBBBBB", boyut, boyut, 8, 2, 0, 0, 0))
        + parca(b"IDAT", zlib.compress(ham, 9))
        + parca(b"IEND", b"")
    )


def istek(yol, yontem, govde=None, tur=None):
    r = urllib.request.Request(URL + yol, data=govde, method=yontem)
    r.add_header("Authorization", "Bearer " + ANAHTAR)
    r.add_header("apikey", ANAHTAR)
    if tur:
        r.add_header("Content-Type", tur)
    try:
        with urllib.request.urlopen(r) as c:
            return c.status, c.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode("utf-8", "replace")


HEDEFLER = [
    ("1079ba5a-70ff-46f2-908b-dcbbd0b8a982", (46, 134, 193)),   # orcun - mavi
    ("9a9a742c-47e5-4d0b-bbea-ceef90d275e0", (39, 174, 96)),    # ucuncu - yesil
]

for kimlik, renk in HEDEFLER:
    yol = f"{kimlik}/ornek-avatar.png"
    durum, cevap = istek(
        f"/storage/v1/object/profil-fotograflari/{yol}",
        "POST",
        png(renk),
        "image/png",
    )
    if durum == 409:  # zaten var -> uzerine yaz
        durum, cevap = istek(
            f"/storage/v1/object/profil-fotograflari/{yol}",
            "PUT",
            png(renk),
            "image/png",
        )
    print("yukleme", durum, yol)

    durum, cevap = istek(
        f"/rest/v1/profiller?id=eq.{kimlik}",
        "PATCH",
        ('{"fotograflar":["%s"]}' % yol).encode(),
        "application/json",
    )
    print("profil guncelleme", durum)

