    setSonuclar([])
    setDurum(yeni.trim().length === 0 ? null : t('kisiler.enAzIki'))
    return
  }

  try {
    const bulunanlar = await kisiAra(yeni)
    if (istekNo !== sonIstekRef.current) return

    const satirlar: SatirVerisi[] = await Promise.all(
