import puppeteer from 'puppeteer-core'
import fs from 'node:fs'

const KROM = [
  'C:/Program Files/Google/Chrome/Application/chrome.exe',
  'C:/Program Files (x86)/Google/Chrome/Application/chrome.exe',
].find((y) => fs.existsSync(y))

const TABAN = 'https://slooin.expo.app'
const [CIKTI, ARANAN] = process.argv.slice(2)

const tarayici = await puppeteer.launch({ executablePath: KROM, headless: 'new' })
try {
  const sayfa = await tarayici.newPage()
  await sayfa.setViewport({ width: 390, height: 844, deviceScaleFactor: 2 })

  await sayfa.goto(`${TABAN}/giris`, { waitUntil: 'networkidle0', timeout: 60000 })
  await new Promise((c) => setTimeout(c, 1200))
  const kutular = await sayfa.$$('input')
  await kutular[0].type('05550000000', { delay: 20 })
  await kutular[1].type('[SIR-GIZLENDI]', { delay: 20 })
  await sayfa.evaluate(() => {
    const d = [...document.querySelectorAll('div,button')].find(
      (o) => o.textContent?.trim() === 'Giriş yap'
    )
    d?.dispatchEvent(new MouseEvent('click', { bubbles: true }))
  })
  await new Promise((c) => setTimeout(c, 4000))

  await sayfa.goto(`${TABAN}/`, { waitUntil: 'networkidle0' })
  await new Promise((c) => setTimeout(c, 2500))

  const arama = await sayfa.$('input')
  if (!arama) throw new Error('arama kutusu bulunamadi')
  await arama.click()
  await arama.type(ARANAN, { delay: 60 })
  await new Promise((c) => setTimeout(c, 2500))

  await sayfa.screenshot({ path: CIKTI })
  console.log(CIKTI)
} finally {
  await tarayici.close()
}

