/** Profil ekraninda turuncu band ile "Anilar" arasindaki gercek boslugu olcer. */
import puppeteer from 'puppeteer-core'
import fs from 'node:fs'

const KROM = [
  'C:/Program Files/Google/Chrome/Application/chrome.exe',
  'C:/Program Files (x86)/Google/Chrome/Application/chrome.exe',
].find((y) => fs.existsSync(y))

const TABAN = 'https://slooin.expo.app'
const tarayici = await puppeteer.launch({ executablePath: KROM, headless: 'new' })
try {
  const sayfa = await tarayici.newPage()
  await sayfa.setViewport({ width: 390, height: 844, deviceScaleFactor: 2 })

  await sayfa.goto(`${TABAN}/giris`, { waitUntil: 'networkidle0', timeout: 60000 })
  const alanlar = await sayfa.$$('input')
  await alanlar[0].type('05550000000', { delay: 12 })
  await alanlar[1].type('[SIR-GIZLENDI]', { delay: 12 })
  await sayfa.evaluate(() => {
    const h = [...document.querySelectorAll('div,span')].find(
      (e) => e.textContent?.trim() === 'Giriş yap' && e.children.length === 0
    )
    h?.closest('[role="button"]')?.click() ?? h?.click()
  })
  await new Promise((c) => setTimeout(c, 4000))
  await sayfa.goto(`${TABAN}/profil`, { waitUntil: 'networkidle0' })
  await new Promise((c) => setTimeout(c, 2500))

  const olcum = await sayfa.evaluate(() => {
    const turuncu = [...document.querySelectorAll('div')].find((d) => {
      const s = getComputedStyle(d)
      return s.backgroundColor === 'rgb(254, 120, 19)' && d.getBoundingClientRect().height > 200
    })
    const anilar = [...document.querySelectorAll('div,span')].find(
      (e) => e.textContent?.trim() === 'Anılar' && e.children.length === 0
    )
    if (!turuncu || !anilar) return { hata: 'oge bulunamadi' }
    const a = turuncu.getBoundingClientRect()
    const b = anilar.getBoundingClientRect()
    // Aradaki tum ogeleri de listele
    const aradakiler = []
    let n = turuncu.nextElementSibling
    while (n) {
      const r = n.getBoundingClientRect()
      aradakiler.push({
        etiket: (n.textContent || '').trim().slice(0, 24),
        yukseklik: Math.round(r.height),
        ustPay: getComputedStyle(n).marginTop,
      })
      n = n.nextElementSibling
    }
    return {
      bandAlt: Math.round(a.bottom),
      anilarUst: Math.round(b.top),
      bosluk: Math.round(b.top - a.bottom),
      bandinKardesleri: aradakiler.slice(0, 5),
    }
  })
  console.log(JSON.stringify(olcum, null, 1))
} finally {
  await tarayici.close()
}

